const listUnhealthyEnabledHealthChecksByFabric = `-- name: ListUnhealthyEnabledHealthChecksByFabric :many
SELECT id FROM dns_health_checks
WHERE fabric_id = $1
  AND status = 'unhealthy'::dns_health_check_status
  AND enabled = true
`

// IDs only — the bundle assembler uses the set to skip records
// whose health_check_id is unhealthy. The renderer's `unhealthy`
// input is a set[uuid], so we return the raw IDs.
func (q *Queries) ListUnhealthyEnabledHealthChecksByFabric(ctx context.Context, fabricID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listUnhealthyEnabledHealthChecksByFabric, fabricID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
